test-case.test:
(: 3 Full-Text Selections: Test valid weight value (within positive part of range) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {100.0}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (at low end of range absolute value) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {0.0}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (at high positive end of range) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {1000.0}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
