(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
declare variable $weight-1 := -100;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {$weight-1}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
declare variable $weight-1 := -1000;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {$weight-1}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test valid weight value (within negative part of range) :)
declare variable $input-context external;
declare variable $weight-1 := -100;
declare variable $weight-2 := -500;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {$weight-1 + $weight-2}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test invalid weight value (just greater than high positive end of range) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {1000.1}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test invalid weight value (just outside high negative end of range) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {-1000.1}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test invalid weight value (not numeric value) :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p contains text "everything" weight {"abcd"}
order by $sc
return $p }
</paragraphs>

(: 3 Full-Text Selections: Test invalid grammar for weight specification, see bug 7247. :)
declare variable $input-context external;
a contains text {"something"} weight element ftand {"other"}

(: 3 Full-Text Selections: Test ftcontains with valid weight value fails :)
declare variable $input-context external;
<paragraphs>
{ for $p score $sc in $input-context//div2[@id="id-minimal-conformance"]//p
where $p ftcontains "everything" weight {1.0}
order by $sc
return $p }
</paragraphs>
